@st.cache_data(ttl=30, show_spinner=False)
def load_portfolios():
    rows = db().table("portfolios").select("*").order("portfolio_number").execute().data
    return rows

@st.cache_data(ttl=20, show_spinner=False)
def load_holdings(portfolio_id):
    return db().table("holdings").select("*").eq("portfolio_id", portfolio_id).order("ticker").execute().data

@st.cache_data(ttl=20, show_spinner=False)
def load_transactions(portfolio_id):
    return (
        db().table("transactions")
        .select("*")
        .eq("portfolio_id", portfolio_id)
        .order("trade_date", desc=True)
        .order("created_at", desc=True)
        .execute().data
    )

@st.cache_data(ttl=20, show_spinner=False)
def load_theses(portfolio_id):
    return (
        db().table("theses")
        .select("*")
        .eq("portfolio_id", portfolio_id)
        .order("ticker")
        .execute().data
    )

@st.cache_data(ttl=20, show_spinner=False)
def load_snapshots(portfolio_id):
    return (
        db().table("portfolio_snapshots")
        .select("*")
        .eq("portfolio_id", portfolio_id)
        .order("snapshot_date")
        .execute().data
    )

def clear_cache():
    load_portfolios.clear()
    load_holdings.clear()
    load_transactions.clear()
    load_theses.clear()
    load_snapshots.clear()

def current_portfolio(portfolios, number):
    return next(p for p in portfolios if p["portfolio_number"] == number)

def get_holding(holdings, ticker):
    return next((h for h in holdings if h["ticker"] == ticker), None)

def metrics_from_holdings(holdings, price_overrides=None):
    """Calculate tracker metrics, optionally using live Google Sheet prices."""
    price_overrides = price_overrides or {}
    invested = sum(float(h.get("quantity",0)) * float(h.get("avg_buy_price",0)) for h in holdings)
    current = 0.0
    missing = 0
    for h in holdings:
        ticker = h.get("ticker", "")
        live = price_overrides.get(ticker)
        if live is None:
            live = price_overrides.get(normalize_ticker(ticker))
        if live is None:
            ltp = h.get("ltp")
        else:
            ltp = live
        if ltp is None:
            missing += 1
        else:
            current += float(h.get("quantity",0)) * float(ltp)
    pnl = current - invested if missing == 0 else None
    ret = pnl / invested * 100 if pnl is not None and invested else None
    return invested, current, pnl, ret, missing

# -----------------------------
# Prices — Google Finance via Google Sheets
# -----------------------------
def normalize_ticker(ticker):
    """Normalize common NSE ticker formats to a plain NSE symbol."""
    ticker = str(ticker or "").strip().upper()
    for suffix in (".NS", ":NSE"):
        if ticker.endswith(suffix):
            ticker = ticker[:-len(suffix)]
    return ticker


def google_symbol(ticker):
    """Return the Google Finance symbol used inside GOOGLEFINANCE()."""
    return f"NSE:{normalize_ticker(ticker)}"


def benchmark_symbol(ticker):
    """Normalize benchmark names/tickers for the Google Sheet feed."""
    value = str(ticker or "").strip().upper()
    if not value:
        return ""
    if value in {"NIFTY 50", "NIFTY50", "NSE:NIFTY50", "^NSEI"}:
        return "NIFTY50"
    return normalize_ticker(value)


def sheet_to_csv_url(sheet_url):
    """
    Accept the published Google Sheets URL supplied by the user.

    Examples accepted:
      https://docs.google.com/spreadsheets/d/e/.../pubhtml
      https://docs.google.com/spreadsheets/d/e/.../pub
      https://docs.google.com/spreadsheets/d/.../edit
      A direct CSV URL
    """
    url = str(sheet_url or "").strip()
    if not url:
        return ""

    # Already a CSV/export URL.
    if "output=csv" in url or "/export?format=csv" in url:
        return url

    # Published-to-web URL:
    # .../pubhtml  -> .../pub?output=csv
    if "/pubhtml" in url:
        return url.split("/pubhtml", 1)[0] + "/pub?output=csv"

    # Published URL without the HTML suffix.
    if re.search(r"/pub(?:\?|$)", url):
        return url.split("?", 1)[0] + "?output=csv"

    # Normal Google Sheets document URL.
    match = re.search(r"/spreadsheets/d/([^/]+)", url)
    if match:
        spreadsheet_id = match.group(1)
        return f"https://docs.google.com/spreadsheets/d/{spreadsheet_id}/export?format=csv"

    return url


@st.cache_data(ttl=15, show_spinner=False)
def fetch_prices_from_google_sheet(sheet_url, tickers):
    """
    Read live prices from the *Companies* tab of the Capital Sight Google Sheet.

    The Companies tab is the single source of truth for current prices. It must
    contain at least: Company | Price | Ticker. The Price cells can be populated
    by GOOGLEFINANCE() in Google Sheets.

    We deliberately target the Companies tab instead of the spreadsheet's first
    tab (Home), which was the cause of the previous ``Ticker and Price`` error.
    """
    if not sheet_url or not tickers:
        return {}

    wanted = {normalize_ticker(t) for t in tickers if str(t).strip()}
    wanted_compact = {x.replace(" ", "") for x in wanted}
    if not wanted:
        return {}

    try:
        # Primary feed: explicit Companies tab. This works with a normal Sheet
        # URL when the sheet is accessible to the Streamlit app, and with a
        # published-to-web URL when supplied in Secrets.
        df = normalize_sheet_columns(fetch_google_sheet_tab(sheet_url, "Companies"))

        if "ticker" not in df.columns or "price" not in df.columns:
            raise RuntimeError(
                "The Companies tab must contain columns named Ticker and Price."
            )

        prices = {}
        for _, row in df.iterrows():
            key = normalize_ticker(row.get("ticker"))
            if not key:
                continue
            if key not in wanted and key.replace(" ", "") not in wanted_compact:
                continue

            raw = row.get("price")
            if pd.isna(raw):
                continue
            try:
                price = float(str(raw).replace(",", "").replace("₹", "").strip())
            except Exception:
                continue
            if price > 0:
                prices[key] = price

        result = {}
        for original in tickers:
            normalized = normalize_ticker(original)
            if normalized in prices:
                result[original] = prices[normalized]
                continue
            compact = normalized.replace(" ", "")
            for key, value in prices.items():
                if key.replace(" ", "") == compact:
                    result[original] = value
                    break
        return result

    except Exception as e:
        raise RuntimeError(
            "Could not read live prices from the Google Sheet Companies tab. "
            "Make sure the sheet is accessible to the Streamlit app (recommended: "
            "Share → General access → Anyone with the link → Viewer, or publish the "
            "Companies tab to the web) and that Companies has Ticker and Price columns. "
            f"Technical detail: {e}"
        )

def google_sheet_tab_url(sheet_url, sheet_name):
    """Build a CSV URL for a specific tab in the same Google Sheet."""
    url = str(sheet_url or "").strip()
    if not url:
        return ""
    match = re.search(r"/spreadsheets/d/([^/]+)", url)
    if match and "/d/e/" not in url:
        spreadsheet_id = match.group(1)
        return (
            f"https://docs.google.com/spreadsheets/d/{spreadsheet_id}/gviz/tq"
            f"?tqx=out:csv&sheet={quote(str(sheet_name))}"
        )
    if "/pubhtml" in url:
        base = url.split("/pubhtml", 1)[0] + "/pub"
        return base + "?output=csv&sheet=" + quote(str(sheet_name))
    if re.search(r"/pub(?:\?|$)", url):
        base = url.split("?", 1)[0]
        return base + "?output=csv&sheet=" + quote(str(sheet_name))
    return url


def _promote_sheet_header(df, sheet_name):
    """Promote the real table-header row in tabs that have title/instruction rows above it."""
    if df is None or df.empty:
        return pd.DataFrame()

    # Companies and Trackers already have headers on row 1.
    expected = {
        "companies": {"company", "ticker", "price"},
        "trackers": {"tracker", "purpose / theme"},
        "research notes": {"research note id", "company", "ticker", "research notes"},
        "research graph": {"graph id", "company", "ticker", "relationship"},
        "management promise tracker": {"company", "ticker", "promise / management statement"},
        "thematic industry map": {"theme", "industry", "company", "ticker"},
        "company quality score": {"company", "ticker", "business quality (0-5)", "quality score / 100"},
    }
    wanted = expected.get(str(sheet_name).strip().lower(), {"company", "ticker"})

    # Read without assuming the first row is the header, then locate the row
    # containing the strongest set of expected column names.
    raw = df.copy()
    best_idx = 0
    best_score = -1
    scan_rows = min(len(raw), 12)
    for idx in range(scan_rows):
        vals = {str(v).strip().lower() for v in raw.iloc[idx].tolist() if pd.notna(v) and str(v).strip()}
        score = len(vals & wanted)
        if score > best_score:
            best_score = score
            best_idx = idx

    if best_idx == 0 and best_score <= 0:
        return df

    header = [str(v).strip() if pd.notna(v) else "" for v in raw.iloc[best_idx].tolist()]
    out = raw.iloc[best_idx + 1:].copy()
    out.columns = header
    # Remove completely blank/unnamed columns created by the title/instruction area.
    keep = [c for c in out.columns if str(c).strip()]
    out = out[keep]
    return out.reset_index(drop=True)


@st.cache_data(ttl=15, show_spinner=False)
def fetch_google_sheet_tab(sheet_url, sheet_name):
    """Read one named tab from the Capital Sight Google Sheet, including tabs with title rows."""
    if not sheet_url:
        return pd.DataFrame()
    csv_url = google_sheet_tab_url(sheet_url, sheet_name)
    try:
        # Do not let pandas assume row 1 is the header. Several Capital Sight
        # research tabs intentionally have a title + instruction block first.
        raw = pd.read_csv(csv_url, header=None)
        return _promote_sheet_header(raw, sheet_name)
    except Exception as e:
        raise RuntimeError(f"Could not read the '{sheet_name}' tab from the Google Sheet: {e}")


def normalize_sheet_columns(df):
    out = df.copy()
    out.columns = [str(c).strip().lower() for c in out.columns]
    return out


def sheet_company_match(df, ticker, company=None):
    if df.empty:
        return None
    d = normalize_sheet_columns(df)
    ticker_n = normalize_ticker(ticker)
    if "ticker" in d.columns:
        m = d[d["ticker"].astype(str).map(normalize_ticker) == ticker_n]
        if not m.empty:
            return m.iloc[0].to_dict()
    if company and "company" in d.columns:
        target = str(company).strip().lower()
        m = d[d["company"].astype(str).str.strip().str.lower() == target]
        if not m.empty:
            return m.iloc[0].to_dict()
    return None


def google_sheet_url_for_research():
    return str(secret("GOOGLE_SHEET_URL") or secret("GOOGLE_SHEET_CSV_URL") or DEFAULT_GOOGLE_SHEET_URL).strip()


def load_sheet_scorecard(ticker, company=None):
    url = google_sheet_url_for_research()
    if not url:
        return None
    try:
        return sheet_company_match(fetch_google_sheet_tab(url, "Company Quality Score"), ticker, company)
    except Exception:
        return None


def load_sheet_research_notes(ticker, company=None):
    url = google_sheet_url_for_research()
    if not url:
        return pd.DataFrame()
    try:
        df = normalize_sheet_columns(fetch_google_sheet_tab(url, "Research Notes"))
        if df.empty:
            return df
        ticker_n = normalize_ticker(ticker)
        if "ticker" in df.columns:
            return df[df["ticker"].astype(str).map(normalize_ticker) == ticker_n]
        if company and "company" in df.columns:
            return df[df["company"].astype(str).str.strip().str.lower() == str(company).strip().lower()]
    except Exception:
        pass
    return pd.DataFrame()


def load_sheet_tab_filtered(tab_name, ticker, company=None):
    """Load any research tab from the same Google Sheet and filter by company/ticker when possible."""
    url = google_sheet_url_for_research()
    if not url:
        return pd.DataFrame()
    try:
        df = normalize_sheet_columns(fetch_google_sheet_tab(url, tab_name))
        if df.empty:
            return df
        ticker_n = normalize_ticker(ticker)
        if "ticker" in df.columns:
            matched = df[df["ticker"].astype(str).map(normalize_ticker) == ticker_n]
            if not matched.empty:
                return matched
        if company and "company" in df.columns:
            target = str(company).strip().lower()
            matched = df[df["company"].astype(str).str.strip().str.lower() == target]
            if not matched.empty:
                return matched
        # These tabs are company-specific research tables. Do not display the
        # entire unfiltered sheet when no row matches; that created blank-looking
        # tables in the UI.
        return pd.DataFrame(columns=df.columns)
    except Exception:
        return pd.DataFrame()


def load_sheet_total_change():
    url = google_sheet_url_for_research()
    if not url:
        return {}
    for tab in ("Trackers", "Companies"):
        try:
            df = normalize_sheet_columns(fetch_google_sheet_tab(url, tab))
        except Exception:
            continue
        if "tracker" not in df.columns or "total % change" not in df.columns:
            continue
        out = {}
        for _, row in df.iterrows():
            key = str(row.get("tracker", "")).strip().lower()
            raw = row.get("total % change")
            if not key or pd.isna(raw):
                continue
            try:
                out[key] = float(str(raw).strip().replace("%", ""))
            except Exception:
                continue
        return out
    return {}


def refresh_prices_and_snapshot(portfolio, holdings):
    # Always bypass the Streamlit price cache when explicitly/automatically refreshing.
    # Google Sheets is the source of truth for the latest GOOGLEFINANCE() value.
    fetch_prices_from_google_sheet.clear()
    fetch_google_sheet_tab.clear()

    tickers = sorted({h["ticker"] for h in holdings if h.get("ticker")})
    sheet_url = str(
        secret("GOOGLE_SHEET_URL") or secret("GOOGLE_SHEET_CSV_URL") or DEFAULT_GOOGLE_SHEET_URL
    ).strip()

    if not sheet_url:
        raise RuntimeError(
            "Google Finance is not configured. Add GOOGLE_SHEET_URL "
            "to Streamlit Secrets."
        )

    prices = fetch_prices_from_google_sheet(sheet_url, tuple(tickers))

    updated = 0
    for h in holdings:
        original_ticker = h.get("ticker", "")
        normalized_ticker = normalize_ticker(original_ticker)

        # Prices are keyed using the exact Supabase ticker where possible,
        # but matching is case/format insensitive (ITC == itc, etc.).
        price = prices.get(original_ticker)
        if price is None:
            price = prices.get(normalized_ticker)
        if price is None:
            for key, value in prices.items():
                if normalize_ticker(key).replace(" ", "") == normalized_ticker.replace(" ", ""):
                    price = value
                    break

        if price is None:
            continue

        db().table("holdings").update({
            "ltp": float(price),
            "price_updated_at": datetime.utcnow().isoformat()
        }).eq("id", h["id"]).execute()
        h["ltp"] = float(price)
        updated += 1

    invested, current, pnl, ret, missing = metrics_from_holdings(holdings, live_sheet_prices)

    if missing == 0:
        benchmark = benchmark_symbol(portfolio.get("benchmark_ticker"))
        benchmark_price = None

        if benchmark:
            # The Sheet can use either NIFTY50 or NIFTY 50.
            bp = fetch_prices_from_google_sheet(
                sheet_url,
                (benchmark, "NIFTY 50") if benchmark == "NIFTY50" else (benchmark,)
            )
            benchmark_price = (
                bp.get(benchmark)
                or bp.get("NIFTY 50")
            )

        db().table("portfolio_snapshots").upsert({
            "portfolio_id": portfolio["id"],
            "snapshot_date": str(date.today()),
            "portfolio_value": current,
            "invested_value": invested,
            "return_pct": ret,
            "benchmark_value": benchmark_price,
        }, on_conflict="portfolio_id,snapshot_date").execute()

    return updated


def auto_refresh_selected_portfolio(portfolio, holdings):
    """
    Refresh prices automatically when the app is opened/refreshed.
    Cached for 60 seconds so normal page navigation does not hammer the feed.
    """
    if not holdings:
        return 0

    try:
        updated = refresh_prices_and_snapshot(portfolio, holdings)
        # The cached DB holdings may contain the previous LTP. Invalidate it so
        # the page renders the values just written to Supabase.
        clear_cache()
        return updated
    except Exception:
        # Do not break the whole public dashboard if the external feed
        # is temporarily unavailable. The last stored LTP remains visible.
        return 0


