        ticker=a.text_input("Ticker",placeholder="RELIANCE.NS").upper().strip()
        company=b.text_input("Company")
        action=c.selectbox("Transaction type",["BUY","SELL"])
        qty=d.number_input("Quantity",min_value=0.0,step=1.0)
